import * as XLSX from '@e965/xlsx';
export function workbook(options:{type?:'xls'|'xlsx';net?:number;units?:number;fraction?:boolean;missingRate?:boolean;name?:string}={}){const book=XLSX.utils.book_new(),s:XLSX.WorkSheet={};const cell=(r:number,c:number,v:string|number)=>{s[XLSX.utils.encode_cell({r:r-1,c:c-1})]={t:typeof v==='number'?'n':'s',v};};cell(1,1,'노임대장-일용직 (2026년10월)');cell(2,31,'합성 현장');cell(4,5,'성 명');cell(4,22,'출역\n일수');cell(4,31,'차인지급액');cell(6,1,1);cell(6,5,options.name??'합성 근로자');cell(6,6,1);cell(7,6,1.5);cell(6,22,options.units??2.5);if(!options.missingRate)cell(6,23,100000);cell(6,24,250000);[1000,100,200,300,400,options.fraction?50.5:50].forEach((v,i)=>cell(6,25+i,v));cell(6,31,options.net??247950);cell(6,32,2050);s['!ref']='A1:AG8';XLSX.utils.book_append_sheet(book,s,'현장 노임 단가(일용직)');return new Uint8Array(XLSX.write(book,{type:'buffer',bookType:options.type==='xlsx'?'xlsx':'biff8'}));}
